pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address a1, address a2, string memory t1, string memory t2) public {
        vm.assume(a1 != a2);
        address vader = address(this);
        address usdv = address(this);
        address vault = address(this);
        c.init(vader, usdv, vault);

        uint id1 = c.proposalCount() + 1;
        c.newAddressProposal(a1, t1);
        uint id2 = id1 + 1;
        c.newAddressProposal(a2, t2);

        assertEq(c.proposalCount(), id2);
    }
}
